 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3:
                continue
            # A marker is the center of a small framed motif.
            for dc in range(-2, 3):
                if 0 <= r - 2 < h and 0 <= c + dc < w:
                    out[r - 2][c + dc] = 5
                if 0 <= r + 2 < h and 0 <= c + dc < w:
                    out[r + 2][c + dc] = 8
            for dr in (-1, 0, 1):
                for dc in (-2, 2):
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = 2
            if 0 <= r - 1 < h:
                out[r - 1][c] = 5
            # The base row extends to both canvas edges in color 2.
            if 0 <= r + 2 < h:
                for cc in range(w):
                    if not c - 2 <= cc <= c + 2:
                        out[r + 2][cc] = 2
            out[r][c] = 3
    return out
